		LmdbStore store = new LmdbStore(directory.toFile(), config);
		store.setExperimentalQueryOptimizations(true);
		repository = new SailRepository(store);
		repository.init();
		var values = SimpleValueFactory.getInstance();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (int subject = 0; subject < SUBJECTS; subject++) {
				for (int predicate = 0; predicate < PREDICATE_COUNT; predicate++) {
					if (subject == 0 && predicate == 1) {
						connection.add(values.createIRI(EX + "s" + subject), values.createIRI(EX + "p" + predicate),
								values.createIRI(EX + "o" + subject % OBJECT_COUNT), values.createIRI(GRAPH));
					} else {
						connection.add(values.createIRI(EX + "s" + subject), values.createIRI(EX + "p" + predicate),
								values.createIRI(EX + "o" + subject % OBJECT_COUNT));
					}
				}
			}
			connection.commit();
			assertEquals(SUBJECTS * PREDICATE_COUNT, connection.size(), "fixture input must be admitted");
		}
		// Reopen the stopped data as one immutable base. An incremental overlay is allowed to have unknown
